#include <cstdint>
#include <map>
#include <utility>
#include <vector>

struct Jump { std::uint64_t from; std::uint64_t to; };

std::vector<std::pair<std::uint64_t, int>> loopHeads(const std::vector<Jump>& jumps)
{
    std::map<std::uint64_t, int> heads;            // sorted by address
    for (const Jump& j : jumps)
        if (j.to <= j.from) ++heads[j.to];
    return { heads.begin(), heads.end() };
}

unitTests:
using H = std::vector<std::pair<std::uint64_t, int>>;
TEST("the example") { CHECK(loopHeads({ { 0x1010, 0x1040 }, { 0x1030, 0x1018 }, { 0x1050, 0x1018 }, { 0x1060, 0x1060 } }) == H({ { 0x1018, 2 }, { 0x1060, 1 } })); }
TEST("only forward jumps") { CHECK(loopHeads({ { 0x10, 0x20 }, { 0x30, 0x40 } }).empty()); }
TEST("nested loops") { CHECK(loopHeads({ { 0x50, 0x30 }, { 0x60, 0x10 } }) == H({ { 0x10, 1 }, { 0x30, 1 } })); }
TEST("no jumps") { CHECK(loopHeads({}).empty()); }

